insert into question_bank_items (id, stage_id, position, question, hint, answer) values (70, 5, 9, 'What is LLM-as-a-judge, and what are its pitfalls?', 'Useful for fuzzy scoring, but a judge you have not validated just moves the trust problem.', ARRAY['Using a strong model to score another model’s output against a rubric — handy where exact-match cannot work, like helpfulness or tone.', 'The pitfalls are real: judges are biased toward verbose or self-authored answers, are sensitive to prompt wording and option order, and are non-deterministic themselves.', 'Mitigate by validating the judge against human labels, giving it a precise rubric, pinning temperature, controlling for position bias, and reserving it for the fuzzy dimensions while using deterministic checks for structure and safety.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (71, 5, 10, 'How do you test an AI feature for bias and fairness?', 'Vary only the protected attribute and compare outcomes.', ARRAY['Use counterfactual tests: take the same input and change only a protected attribute (name, gender, ethnicity signal) and assert the decision or tone does not change when it should not.', 'Measure outcomes across groups on a representative set — not just anecdotes — and watch for quality or refusal rates that differ by group.', 'Cover representational harm too: stereotypes, skew in generated content, and the fact that training data encodes historical bias. Define what "fair" means for the feature up front, since it is a product decision, not a metric.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (72, 5, 11, 'How do you write reliable assertions against a non-deterministic model?', 'Assert the contract and properties, never the exact sentence.', ARRAY['Pin what you can — model version, temperature, seed where supported — and record/replay real responses as fixtures so most tests are fast, free and deterministic.', 'Assert properties, not strings: valid JSON against a schema, required fields present, no forbidden content, length and language constraints, a refusal when it should refuse.', 'For the genuinely fuzzy part, run a scored eval set on a schedule with thresholds and tolerance, treating a score drop as a regression signal rather than a single red build.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (73, 5, 12, 'What safety guardrails would you test on a customer-facing chatbot?', 'Assume users will be adversarial and creative.', ARRAY['Content safety: it refuses harmful, illegal or hateful requests, and resists jailbreaks and role-play framings that try to talk it out of the policy.', 'Boundary and privacy: it stays on-topic, does not invent policies or promise things the business will not honour, and never leaks system prompts, other users’ data or secrets.', 'Robustness and escalation: injection through user input or a pasted document is contained, and it hands off to a human when uncertain instead of confidently guessing. Treat every real bypass as a permanent regression case.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (74, 5, 13, 'How do you test context-window limits, truncation and long inputs?', 'What silently falls off the edge of the prompt is a real bug.', ARRAY['Test at and beyond the window: the system must truncate or summarise deliberately, not silently drop the user’s actual question or the system instructions.', 'Probe the "lost in the middle" effect — models attend less to the middle of a long context — by placing the key fact early, middle and late and checking it is still used.', 'Assert graceful handling of overflow (a clear error or a chunking strategy, never a crash), and watch cost and latency, which scale with input length.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (75, 5, 14, 'How do you monitor an AI feature in production for drift and quality decay?', 'Offline eval is a snapshot; production is where quality actually erodes.', ARRAY['Log inputs, outputs and signals, and watch for input drift (users asking new things) and output drift (the model or a silent vendor update changing behaviour).', 'Track quality proxies continuously: thumbs-down, escalation and retry rates, refusal rate, latency and cost — and alert on trend changes, not single events.', 'Run a scheduled eval against the golden set to catch regressions a vendor update introduced, sample real traffic for human review, and feed every discovered failure back into the eval set.']::text[]);
insert into question_bank_stages (id, lang, position, icon, title) values (6, 'he', 0, '🧭', 'שלב 1 — משאבי אנוש ומוטיבציה');
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (76, 6, 0, 'ספר על הרקע שלך ולמה עברת לאוטומציית בדיקות.', 'ספרו מסלול, לא הקראה של קורות חיים — מה משך אתכם לאוטומציה, ועל מה אתם אחראים היום.', ARRAY['בנו את התשובה בשלושה חלקים: איפה התחלתם, הרגע שבו אוטומציה הפכה למנוף המתבקש, ועל מה אתם אחראים היום. שתי דקות, לא עשר.', 'עגנו את המעבר בכאב קונקרטי — סבב רגרסיה שלקח שלושה ימים ידנית, גרסה שנדחתה כי אישור ידני לא הספיק. קונקרטי תמיד מנצח מופשט.', 'סיימו עם היקף וסטאק: מה אתם מאוטמים היום (UI, API, CI), באילו כלים, וכמה גדולים הסוויטה והצוות.', 'חתמו עם כיוון — מה תרצו לעשות יותר — כדי שהמראיין יוכל לחבר את הסיפור לתפקיד שהוא באמת מגייס אליו.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (77, 6, 1, 'למה אתה עוזב את התפקיד הנוכחי, ומה אתה מחפש בתפקיד הבא?', 'ענו קדימה ולא אחורה: לאן אתם הולכים, לא ממה אתם בורחים.', ARRAY['הציגו תקרת צמיחה ולא תלונה: "לקחתי את הסוויטה מהרצה ידנית לילית לשער של 9 דקות בכל PR, והצעד הבא שאני רוצה פשוט לא קיים שם" — אמין ובטוח.', 'לעולם אל תבקרו אנשים או את המעסיק. מראיינים מסיקים בשקט איך תדברו עליהם בעוד שנה.', 'היו ספציפיים לגבי מה שאתם מחפשים — בעלות על אסטרטגיית בדיקות, עומק ב-CI, בדיקת פיצ’רים מבוססי LLM — וקשרו את זה למשהו בתיאור המשרה.', 'החזיקו עובדה אחת כנה וניטרלית אם ילחצו (ריאורגניזציה, פרויקט שהסתיים, חוזה, מעבר דירה). עמימות נשמעת כמו הסתרה; עובדה פשוטה סוגרת את הנושא.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (78, 6, 2, 'ספר על פרויקט שאתה גאה בו — מה בדיוק הייתה התרומה שלך?', 'STAR, והדגש הוא על "בדיוק": אמרו אני, לא אנחנו, וסיימו במספר.', ARRAY['Situation ו-Task בשני משפטים. את רוב הזמן הקדישו ל-Action — זה החלק שנבחן.', 'השתמשו ב"אני" במכוון. השאלה הזו קיימת כדי להפריד בין מי שעשה את העבודה לבין מי שעמד לידה.', 'כמתו את ה-Result: זמן הרצה מ-40 דקות ל-9, ירידה של שליש בתקלות שדלפו לפרודקשן, שיעור flaky מ-12% לפחות מ-1%. מספר הופך את הסיפור לניתן לבדיקה.', 'הוסיפו דבר אחד שהייתם עושים אחרת היום. מודעות עצמית נשמעת כמו בגרות מקצועית; סיפור מושלם נשמע מתורגל.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (79, 6, 3, 'תאר קונפליקט עם מפתח על באג. איך פתרת אותו?', 'בוחנים ראיות וטון, לא מי ניצח.', ARRAY['בחרו מחלוקת אמיתית עם סיום מקצועי. "מעולם לא היה לי" נשמע או לא כן או לא מעורב.', 'הראו שהובלתם עם ראיות: מקרה שחזיר, לוגים, וידאו, ה-build והסביבה המדויקים — העברת הדיון מדעה לנתונים.', 'הראו שהפרדתם בין נכונות לחומרה. האם זה באג והאם זה חוסם גרסה הן שתי שיחות שונות, והשנייה שייכת לבעל המוצר.', 'סיימו עם מערכת יחסים שנשמרה ועם שינוי מערכתי אחד: תבנית לדיווח באגים, כלל טריאז’, או הגדרת "בוצע" מהודקת יותר.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (80, 6, 4, 'לאן לדעתך אוטומציית QA מתקדמת בשנים הקרובות?', 'הראו עדכניות בלי הייפ — נקבו בשינוי, ואז אמרו מה הוא דורש מהבודקים.', ARRAY['נקבו בשינויים קונקרטיים: בדיקות שעוברות לתוך ה-pipeline כשער ולא כשלב, בדיקות API וחוזה שנושאות עומס שפעם היה על בדיקות UI, ו-AI שמסייע ביצירת בדיקות ובטריאז’ כשלים.', 'אמרו מה לא משתנה: מישהו עדיין צריך להחליט מה נחשב "נכון", להחזיק את מודל הסיכון ולתכנן את האורקל. הכלים רצים מהר; שיקול הדעת לא.', 'היו כנים לגבי המשטח החדש — פיצ’רים מבוססי LLM דורשים ערכות הערכה, תקציב אי-דטרמיניזם ובדיקות בטיחות. זו מיומנות חדשה באמת, לא ישנה בשם חדש.', 'סיימו במה שאתם עושים בפועל: משהו שקראתם, בניתם או שברתם. דעות זולות; פרויקט צד הוא ראיה.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (81, 6, 5, 'ספר על עצמך.', 'פיץ׳ של 60 שניות שמכוון לתפקיד הזה, לא סיפור חיים.', ARRAY['שלושה חלקים: מה אתם עושים היום, הוכחה קונקרטית אחת להשפעה, ולמה התפקיד הזה הוא הצעד הבא. הווה, עבר-כראיה, עתיד.', 'התאימו לתיאור המשרה — פתחו בחלק מהניסיון שהכי מתאים למה שהם מגייסים אליו, וּותרו על השאר.', 'תרגלו לדקה. גמגום כאן קובע את הטון לכל הראיון; תשובה חדה קונה לכם אשראי לשאלות הקשות שבהמשך.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (82, 6, 6, 'מהן ציפיות השכר שלך?', 'עגנו בטווח מבוסס-מחקר, והחזירו לשיחה.', ARRAY['עשו מחקר קודם — נתוני שוק לתפקיד, לסניוריטי ולמיקום — ותנו טווח שאת תחתיתו הייתם באמת מקבלים.', 'הסיטו בעדינות אם מוקדם מדי: "אשמח קודם להבין את ההיקף, אבל לפי השוק אני מסתכל על X–Y". זה מראה הכנה בלי לכלוא אתכם.', 'לעולם אל תמכרו את עצמכם בזול מרוב מתח, ואל תנקבו במספר שאינכם יכולים להצדיק. קשרו את הסכום לערך ולהיקף שאתם מביאים, לא למה שאתם מרוויחים היום.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (83, 6, 7, 'ספר על באג שדלף לפרודקשן. מה למדת?', 'רוצים בעלוּת ותיקון מערכתי, לא נס נטול-אשמה.', ARRAY['בחרו אחד אמיתי וקחו אחריות על חלקכם בלי להפיל חבר לצוות. "מעולם לא שחררתי באג" נשמע או חוסר ניסיון או חוסר כנות.', 'עברו על התגובה: איך התגלה, כמה מהר הוכל, ומה סיבת השורש — לא רק הסימפטום.', 'סיימו במה שהשתנה כדי שסוג הבאג לא יחזור: בדיקה חסרה שנוספה, פער ב-pipeline שנסגר, התראת ניטור שנוצרה. לקח שנלמד הוא מערכת שהשתנתה, לא החלטה להיזהר יותר.']::text[]);